-- Disposable fixture only. Every write rolls back.
begin;
create function test.plan_rows() returns jsonb language sql immutable as $$select '[{"equipmentId":"20000000-0000-0000-0000-000000000001","equipmentCode":"QC10","equipmentName":"Untrusted name","sourceLabel":"QC 10","group":"QC","maintenanceLevel":"I - theo tháng","materials":[{"key":"grease","name":"Mỡ","unit":"kg","quantity":20,"source":"maintenance_consumable"}]}]'::jsonb$$;
create function test.plan_print() returns jsonb language sql immutable as $$select '{"company":"Fixture company","department":"Fixture department","recipient":"","warehouse":"","consumableWarehouse":"","documentDay":"2026-10-22"}'::jsonb$$;
grant execute on function test.plan_rows(),test.plan_print() to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
insert into test.results values('plan_run',public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),'78000000-0000-0000-0000-000000000001'));
select test.ok(public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),'78000000-0000-0000-0000-000000000001')=(select id from test.results where name='plan_run'),'identical retry returns same run');
select test.ok(public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),gen_random_uuid())=(select id from test.results where name='plan_run'),'new key with same content reuses snapshot');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-30','group',test.plan_rows(),test.plan_print(),'78000000-0000-0000-0000-000000000001')$q$,'22023','changed payload cannot reuse request key');
insert into test.results values('plan_regroup',public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','date',test.plan_rows(),test.plan_print(),gen_random_uuid()));
select test.ok((select count(distinct snapshot#>>'{rows,0,caseId}')=1 from public.maintenance_requisition_runs),'regrouping reuses equipment/day case');
select test.ok((select snapshot#>>'{rows,0,equipmentName}'='QC fixture' from public.maintenance_requisition_runs limit 1),'catalog name comes from database');
select test.ok((select count(*)=1 from public.work_cases where id in (select (snapshot#>>'{rows,0,caseId}')::uuid from public.maintenance_requisition_runs) and tracking_only and kind='maintenance' and actual_ended_at is null),'one open tracking maintenance case');
select test.ok((select count(*)=1 from public.repair_work_items i join public.repair_orders o on o.id=i.repair_order_id where o.case_id in (select (snapshot#>>'{rows,0,caseId}')::uuid from public.maintenance_requisition_runs) and i.performed_on is null and i.completed_at is null and i.execution_status='waiting_shutdown'),'planning never implies performed or completed');
select test.ok((select count(*)=0 from public.repair_material_usages u join public.repair_work_items i on i.id=u.repair_work_item_id join public.repair_orders o on o.id=i.repair_order_id where o.case_id in (select (snapshot#>>'{rows,0,caseId}')::uuid from public.maintenance_requisition_runs)),'planning never implies material usage');
select test.fails($q$update public.maintenance_requisition_runs set planned_day='2026-10-01'$q$,'42501','snapshots cannot be edited directly');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-29','group',test.plan_rows()||jsonb_set(jsonb_set(test.plan_rows()->0,'{equipmentId}','"20000000-0000-0000-0000-000000000002"'),'{equipmentCode}','"RTG22"'),test.plan_print(),gen_random_uuid())$q$,'22023','foreign equipment rolls back the entire batch');
select test.ok((select count(*)=0 from public.work_cases where summary like 'Kế hoạch bảo dưỡng 2026-10-29%'),'no partial case remains after failed batch');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-29','group',jsonb_set(test.plan_rows(),'{0,materials,0,quantity}','0'),test.plan_print(),gen_random_uuid())$q$,'22023','zero quantity rejected');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-29','group',jsonb_set(test.plan_rows(),'{0,materials,0,source}','null'),test.plan_print(),gen_random_uuid())$q$,'22023','null material source rejected');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select test.ok((select count(*)=2 from public.maintenance_requisition_runs),'supply role reads saved requisitions');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),gen_random_uuid())$q$,'42501','supply role cannot create maintenance cases');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
select test.ok((select count(*)=0 from public.maintenance_requisition_runs),'other workspace cannot read snapshots');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),gen_random_uuid())$q$,'42501','other workspace cannot write snapshots');
set local role anon;
select test.fails($q$select * from public.maintenance_requisition_runs$q$,'42501','anonymous cannot read plans');
select test.fails($q$select public.save_maintenance_requisition('00000000-0000-0000-0000-000000000001','2026-10-31','group',test.plan_rows(),test.plan_print(),gen_random_uuid())$q$,'42501','anonymous cannot execute save');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
insert into test.results values('plan_v3',public.save_maintenance_requisition_v3('00000000-0000-0000-0000-000000000001','2026-10-31','2026-11-02','planned',null,'group',test.plan_rows(),test.plan_print(),'source.pdf',repeat('a',64),'78000000-0000-0000-0000-000000000010'));
select test.ok((select document_day='2026-11-02' and planned_day='2026-10-31' and snapshot#>>'{print,documentDay}'='2026-11-02' and source_filename='source.pdf' and source_sha256=repeat('a',64) from public.maintenance_requisition_runs where id=(select id from test.results where name='plan_v3')),'v3 saves date and source in initial immutable insert');
select test.ok(public.save_maintenance_requisition_v3('00000000-0000-0000-0000-000000000001','2026-10-31','2026-11-02','planned',null,'group',test.plan_rows(),test.plan_print(),'source.pdf',repeat('a',64),'78000000-0000-0000-0000-000000000010')=(select id from test.results where name='plan_v3'),'v3 identical retry does not mutate snapshot');
select test.fails($q$select public.save_maintenance_requisition_v3('00000000-0000-0000-0000-000000000001','2026-10-31','2026-11-02','planned',null,'group',test.plan_rows(),test.plan_print(),'changed.pdf',repeat('b',64),'78000000-0000-0000-0000-000000000010')$q$,'22023','source file is part of retry fingerprint');
select test.fails($q$select public.save_maintenance_requisition_v3('00000000-0000-0000-0000-000000000001','2026-10-31','2026-11-02','supplemental','Additional actual shortfall','group',test.plan_rows(),test.plan_print(),'source.pdf',repeat('a',64),gen_random_uuid())$q$,'22023','supplement requires standard workspace material');
insert into test.results values('plan_supplement',public.save_maintenance_requisition_v3('00000000-0000-0000-0000-000000000001','2026-10-31','2026-11-03','supplemental','Additional actual shortfall','group',jsonb_set(test.plan_rows(),'{0,materials}',jsonb_build_array(jsonb_build_object('key','catalog:30000000-0000-0000-0000-000000000001:warehouse','name','Fixture bearing','unit','cai','quantity',2,'source','warehouse','catalogueCode','VT001'))),test.plan_print(),'source.pdf',repeat('a',64),gen_random_uuid()));
select test.ok((select voucher_kind='supplemental' and supplement_note='Additional actual shortfall' and snapshot#>>'{print,voucherKind}'='supplemental' and snapshot#>>'{rows,0,materials,0,quantity}'='2' from public.maintenance_requisition_runs where id=(select id from test.results where name='plan_supplement')),'supplement contains only explicit additional quantities');
select test.ok((select count(distinct snapshot#>>'{rows,0,caseId}')=1 from public.maintenance_requisition_runs),'planned and supplemental vouchers reuse same equipment/day case');
reset role;
select test.ok((select not prosecdef from pg_proc where oid='public.save_maintenance_requisition(uuid,date,text,jsonb,jsonb,uuid)'::regprocedure),'public wrapper uses invoker security');
select test.fails($q$delete from public.maintenance_requisition_runs$q$,'42501','immutable snapshot trigger applies to owner too');
rollback;
